import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"遯","description":"高島易斷 - 遯","frontmatter":{"title":"遯","description":"高島易斷 - 遯"},"headers":[],"relativePath":"classics/takashima/033.md","filePath":"classics/takashima/033.md"}'),i={name:"classics/takashima/033.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="遯" tabindex="-1">遯 <a class="header-anchor" href="#遯" aria-label="Permalink to “遯”">​</a></h1><h2 id="遯-1" tabindex="-1">遯 <a class="header-anchor" href="#遯-1" aria-label="Permalink to “遯”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>遁：亨，小利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《遁》，陰長之卦，小人方進，君子道消。邪正不同居，陰陽不兩立，君子當此，若不隱遁，必受其害。當《遁》而遁，遁而後通，故曰“遁亨”。“小利貞”者，小指二陰而言也，謂陰道始長，陽道猶未全消，故曰“小利貞”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>天下有山，遁，君子以遠小人，不惡而嚴。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>“天下有山，遁”，天之與山，相去遼遠，不可幾及，是天遠山，非山遠天，在山亦不能怨天之遠也。君子則之，以遠小人，不必顯出惡言，亦未嘗始示和氣，但望之而自覺可畏，即之儼然難犯，使小人不遠而自遠也。“不惡而嚴”，斯為待小人之善法也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問戰徵：防前進有山，山間有敵兵埋伏，致遭敗北。</p><p>○　問營商：恐一時物價漲落不同，相去甚遠。</p><p>○　問功名：宜退隱，不宜進見。君子吉，小人否。</p><p>○　問家宅：此宅近山，前面空闊遼遠，防有陰崇。</p><p>○　問疾病：病有鬼祟，宜敬而遠之，以避居為吉。</p><p>○　問婚姻：二五陰陽，本屬相應，但邪正不同，以謝絕之為吉。</p><p>○　問六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初爻居《艮》之始，《艮》為穴居，又為尾，故曰“遁尾”。賢者避地，入山惟恐不深，入林惟恐不密，不欲使人尾其後也。若乃《遁》而不藏其尾，非真《遁》也，是殆借名山為捷徑，欲藉《遁》以為攸往計耳。古今來高隱不終，不特為猿鶴貽笑，而功猶未成，失即隨之，其危厲，皆自取之耳。故戒之曰“勿用有攸往”，謂其宜遁而不宜往也。《象傳》曰：“不往何災”，蓋往則災來，不往則無災，反言之以阻其往也。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問戰徵：為伏兵言也。埋伏宜深藏不露，使敵不得窺其遺蹟，若藏頭露尾，必致危厲，不如不往也。</p><p>○　問營商：銷賣貨物，宜趕快，不宜落後，並宜首尾一併賣訖，斯可免災。</p><p>○　問功名：龍門燒尾，吉。</p><p>○　問家宅：宜速遷移，落後有災。</p><p>○　問婚姻：《遁》者，避而遠之之謂，婚姻不合。</p><p>○　問六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某來，請佔氣運，筮得《遁》之《同人》。</p><p>斷曰：《遁》卦四陽在外，二陰在內，在外者陽浸而消，在內者陰浸而長。運以得陽為佳，陽消陰長，是好運已退也。今佔得《遁》初爻，初爻以陽居陰，爻辭曰“遁尾，厲，勿用有攸往”，謂好運既退，第留此尾末而已，故“厲”。戒曰“勿用”，是宜退守，毋前往也。運以五年為一度，至上六，則“無不利”矣。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“執之”，“莫之”，兩“之”字，皆指《遁》者言。黃，中央之正色，牛性柔順，革性堅韌。《艮》為皮，故曰“革”；《艮》為手，故曰“執”；二得《坤》氣，《坤》為黃牛，故曰“黃牛”。二居內爻，為成卦之主，上應九五，陰長陽消，應五而實消五，五即因之而《遁》，諸爻亦相隨遁去。二爻欲執而留之，如白駒之詩，所詠“執之維之”者是也。“執之用黃牛之革”，以擬其執留之堅，而莫之遁焉。“勝”者，堪也，“說”者，解脫也，“莫之勝脫”，使之不可逃脫也。諸爻皆言《遁》，二爻獨不言《遁》，《遁》者諸爻，而驅之使《遁》者，二爻也；二既驅之使《遁》，而復欲假意以執之，不令其遁，是小人牢籠之計也。《象傳》曰“固志”，五之《象》曰“正志”，二五之志本不同。二欲藉嘉會之禮，以籠絡五之志，使之不遁，“固志”者，固五之志也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問戰徵：當諸軍逃散之際，獨能堅執固守，為可嘉也。</p><p>○　問營商：固一時貨價逐漲，執守來本，莫能脫售。</p><p>○　問功名：席珍待聘，美玉待沽，功名之兆也。“莫之勝脫”，功名難望矣。</p><p>○　問家宅：此宅陰氣漸盛，居者不利，群思遷移，即欲脫售，一時亦難。</p><p>○　問婚姻：此婚已成，後欲退悔，執柯者甚屬為難。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>友人某，來請佔氣運，筮得《遁》之《姤》。</p><p>斷曰：此卦二陰浸長，四陽浸衰，陰者小人，陽者君子，小人日進，君子日退，故謂之《遁》。以氣運言之，正是運退之時也。“黃牛之革”，物之又軟又韌者，以此係物，物莫能脫，譬言人生為運所縛，雖有志願，終生捆縛，不克施展。今佔二爻，其象如此，運可知矣。</p><p>明治二十九年，佔皇國氣運，筮得《遁》之《姤》。</p><p>斷曰：此卦四陽為二陰所侵，論人事則我為彼所侵，於國亦然。自我國勝清之後，俄、德、法三國，以亞細亞之乎和為口實，使我還付遼東，加之俄法為清國償金斡旋，俄清之交一變，將有事於東洋。方今歐洲諸強國，皆惟競利自圖，約束清國，譬如用“黃牛之革”，縶縛其手足，使之莫能解脫，幾欲瓜分之以為快。而於我國，亦未嘗不欲以此相縛，我惟固守其志，內修軍備，外善辭令，以敦邦交，而不受此籠絡也。此為得計耳。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“系”者，羈絆之義。三以陽剛，居內卦之上，與二陰陽相親比，為二所羈縻，不忍超然遠引，欲《遁》而志不決，故曰“系遁”。凡當《遁》則《遁》，貴速而遠，一有所繫，則憂愁莫定，宛如疾痛之在身，危厲之道也，故曰“有疾厲”。蓋“系”者，三繫於二，陰為之主；“畜”者，二畜於三，陽為之主。以陰系陽則厲，以陽畜陰則吉。“臣妾”者陰象，三陽在二陰之上，故能畜。君子之於臣妾，畜之以供使令，進退無足關重輕也，是以“系遁”不失為吉，至若當大事，必致因循而坐誤也。《象傳》曰：“有疾，憊也”，憊謂力竭而敝憊也。“不可大事也”，大事者，指三一生大節而言，不可或忽也。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問戰徵：軍陣進退，皆有紀律，鼓進金退，最要便捷，一有遲誤，必致大敗也，宜慎。</p><p>○　問營商：貨物當脫售之時，不宜躊躇不決，或繫戀私情，防誤大事。</p><p>○　問功名：時當奸人秉政，宜急流勇退，斯無疾害。</p><p>○　問家宅：此宅不利，主多病厄，宜速遷移，若遲延不去，恐有大禍。</p><p>○　問婚姻：娶嫡不利，娶妾則吉。</p><p>○　問六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>友人某來，請佔商業之盛衰，筮得《遁》之《否》。</p><p>斷曰：三爻以陽居陽，留戀二陰，欲遁不決，致“有疾，厲”。今足下佔問商業，得此三爻，知為商業失敗之象，宜速脫貨，則損失猶微；若惜金而躊躇，則品物之價，日益低落，其所損更大也，謂之“系遁，有疾，厲”。“畜臣妾，吉”者，謂葆此餘資，以畜養家人可也，若欲重興商業，則不可也。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四與初相應，相應必相好，乃初與四好，而四不好初；且四因初之好，而決意遠遁，故曰“好遁”。然在初之好四，亦非真好，不過欲借四以為重，是引用君子之意，若新莽之禮賢下士是也。四則有見於此，不為初所籠絡，而超然遠引，謂爾雖好我，我不好爾，爾不我遁，我則自遁，我行我志而已。四入《乾》，《乾》為君子，故曰“君子吉”。在初之厚貌深情，以為四必感戀情好，不意室邇人遠，一去千里，竟有不可執維者。初處《艮》，《艮》為小子，故曰“小人否”。一說“好遁”者，謂有所好而遁也，猶《論語》“從吾所好”之好。世人所好，在富貴功名，君子所好，在樂天知命，此謂好遁。亦通。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問戰徵：四處《乾》之始，《乾》為健，知進不知退。或軍中有一人謀陷，故作退計以避之。退亦吉也。</p><p>○　問營商：商家以買入為進，賣出為退，四曰“好遁”，知以出貨為得利也。</p><p>○　問功名：爻辭“好遁”，是其人必無意於功名也。然名亦不同，或盜虛名於一時，或垂大業於千秋，君子小人，所由分也。佔者宜自審焉。</p><p>○　問疾病：四《乾》體，爻曰“好遁”，陽《遁》而入陰，其病危矣。然轉危為安，亦《遁》之象，想大人可治，小人難也。</p><p>○　問婚姻：防後有離婚之憂。</p><p>○　問訟事：俗雲“三十六著，走為上著”，“好遁”之謂也。</p><p>○　問六甲：生男。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>親友某來，請佔氣運，筮得《遁》之《漸》。</p><p>斷曰：四居《乾》陽之首，《乾》曰見，不曰隱，乃四為二陰所逼，超然遠遁，是遁而避害也。今足下佔得第四爻，足下躬膺職位，亦知僚屬中，邪正不一，或外面情好敦篤，其中奸計百出，不可不防。足下知其然，不露聲色，決意引退，是明哲保身之要道也。爻辭曰，“九四：好遁，君子吉，小人否”，謂君子飛遁離俗則吉，小人溺情爵祿則否矣。爻象如是，足下其審之。後某果因官制改革，有非職之命。</p><p>一日杉浦重剛氏來曰：方今為千島艦事，以上海英國上等裁判所判決為不當，將再向英國理論，其結局果否？如何？請筮之。筮得《遁》之《漸》。</p><p>斷曰：此卦陰長陽消，為邪強正弱之象。正者必反而受屈，卦象如是。今佔千島艦判審事，得《遁》四爻，《遁》卦二陰在內，長而逼上，至四爻則陰勢已盛，陽氣殆盡，在下面雖假作情好，而內心實陰險莫測。核之千島艦之事，情形符合。我國因千島艦失事，據萬國公法向彼理論，迭經審問，終不得直。蓋現今天下大勢憑強弱，不憑曲直，亦事之無可如何者矣。爻辭曰“好遁”，是教我以退避也，即得退遁，了事而已。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五以陽居陽，剛健中正，雖與六二相應，能知時審勢，應變識幾，超然遠遁。其遁也，不為情移，不為勢屈，意決而志正，洵可嘉美矣，故曰“嘉遁，貞吉”。《象傳》曰“以正志也”，謂九五《遁》得其正，即可以正二之志，是“不惡而嚴”也。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問戰徵：正當敵勢強盛，能以潛遁而返，得保全師，亦可嘉也。</p><p>○　問營商：貨到該處，時價不合，而轉別地，得以獲利，可謂應變而不失其正也，故吉。</p><p>○　問功名：爻以九五為尊，佔得九五，是必功名顯達，位近臺輔。伊尹曰，“臣罔以寵利居成功”，謂能以功成身退者也，故吉。</p><p>○　問家宅：此宅必是南陽諸葛之廬，栗裡陶令之宅也，高風可尚。</p><p>○　問婚姻：二五本陰陽相應，有意議婚，五以其志不同，不允。另就他聘，吉。</p><p>○　問疾病：是陰邪糾纏之症，潛而遁避，可獲吉。</p><p>○　問六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>予親友永井泰次郎，其妻有娠，張筵招予，請卜男女，筮得《遁》之《旅》。</p><p>斷曰：九五《乾》卦，以陽居陽，生男之兆也。《乾》為父，《艮》為少男，他年少男嗣父而續家，老父讓產而隱居，故名此卦曰《遁》。且其辭曰“嘉遁，貞吉”，是有子克家之象。其後果生男子。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>“肥”者饒裕也。卦中諸爻，欲遁而多所繫累，此爻獨無應無比，故無繫累，不復勞顧忌，飄然遠弓，所謂進退綽有餘裕者也，故曰“肥遁，無不利”。《象傳》曰：“無所疑也”，謂上爻居《乾》陽之首，其察勢也明，其見幾也決，首先高遁》，絕無一毫之疑礙也。或謂“嘉遁”如殷微子，如漢張良，“肥遁”如泰伯、伯夷，或又如漢之商山四皓也。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問戰徵：戰事宜進不宜遁，遁必不利；爻曰“肥遁，無不利”，其惟太王避狄遷岐乎？</p><p>○　問營商：商人謀利，往往群焉競逐，今獨能人取我棄，以退為進，則其退反得厚利，故爻曰“肥遁”。</p><p>○　問功名：其人必不以膏梁肥口，能以道義肥躬，故曰“肥遁，無不利”。</p><p>○　問家宅：此宅地位甚高，家道亦富，但利於求財，不利於求名。</p><p>○　問疾病：肥人氣虛，《遁》者，脫也，恐致虛脫。</p><p>○　問婚姻：恐女子貪戀富室子弟，因而私奔。</p><p>○　問六甲：生男。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治十八年三月，以中央亞細亞阿富汗境界事，生英獅俄鷲之葛藤，凡新聞電信所報，論和論戰，主俄主英，諸說紛紛，各國皆有戒意。即如我國，利害所關，亦非淺鮮。因佔其和戰如何，筮得《遁》之《鹹》（明治十八年五月八日）。</p><p>斷曰：內卦為山，屬英，外卦為天，屬俄。山《艮》而止，今觀英國所為，雖頻修戰備，不過虛張聲勢，其實無意於戰也。何者？英之海軍雖強，至如阿富汗中央亞細亞地方，不能專用海軍，若陸軍，在英兵數不多，僅足護國而已。且蘇丹之役，已分遣陸兵不少，他如印度兵，雖派遣於阿富汗高寒之地，不能盡得其力；加之印度各分宗教，兵士各守其宗規，粗食亦不足，即驅而用之，豈能當強俄乎？故欲戰不得不用海軍，用海軍之處，有關通商航海之障礙，可以牽動各國。即可以壓制俄國，在英國無心開戰，可於《艮》止而得其象也。天《乾》而健，今觀俄國所為，俄國遵奉彼得帝遺訓，知進而不知退，意在鯨吞各國以為快，可見俄國有意開戰。合內外卦則為《遁》，是《遁》為英國之氣運，《遁》反卦為《大壯》，是為俄國之氣運。在英之對俄，惟有嚴其守備，使俄無隙可乘，即可斷英俄交涉之結果也。</p>',97)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
